import os, json, glob, hashlib, math

BASE = "storage/shared/atlas/analysis/inquirer_veritas_power_law_sim"
SUMMARY = os.path.join(BASE, "power_law_sim_summary_v4.6_avg.json")
PLOT = os.path.join(BASE, "power_law_sim_v4.6_avg_plot.png")
CSV = os.path.join(BASE, "power_law_sim_output_v4.6_avg.csv")
STRICT_OUT = os.path.join(BASE, "verify_config_v4.6.strict.json")
TOL_OUT = os.path.join(BASE, "verify_config_v4.6.tolerance.json")
README = os.path.join(BASE, "README_VERIFICATION_v4.6.md")

def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for b in iter(lambda: f.read(1<<20), b""):
            h.update(b)
    return h.hexdigest()

def write_json(path, obj):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, indent=2, ensure_ascii=False)

def build_strict():
    outs = []
    sha_list = []
    if os.path.exists(SUMMARY):
        s = sha256(SUMMARY); outs.append({"path": SUMMARY, "sha256": s}); sha_list.append({"path": SUMMARY, "sha256": s})
    if os.path.exists(PLOT):
        s = sha256(PLOT); outs.append({"path": PLOT, "sha256": s}); sha_list.append({"path": PLOT, "sha256": s})
    if os.path.exists(CSV):
        s = sha256(CSV); outs.append({"path": CSV, "sha256": s}); sha_list.append({"path": CSV, "sha256": s})
    if not outs:
        return None
    cfg = {"env": {"python": "3.10", "deps": []}, "data": [], "outputs": outs}
    write_json(STRICT_OUT, cfg)
    # README
    lines = ["# v4.6 Verification (Strict, Auto-Packaged)", "", "Artifacts:"]
    for o in outs:
        lines.append(f"- {o['path']}")
    lines += ["", "Strict config:", f"- {STRICT_OUT}", "", "One-line verify:", f"- python storage/shared/agency_lab/repro_template/v2/verify.py --mode strict --config {STRICT_OUT}", "", "SHA256:"]
    for sh in sha_list:
        lines.append(f"- {sh['path']} → {sh['sha256']}")
    with open(README, "w", encoding="utf-8") as f:
        f.write("\n".join(lines) + "\n")
    return {"written": STRICT_OUT, "sha256": sha_list, "readme": README}

METRIC_MAP = [
    ("avg_cycle_metrics.num_void_cycles_detected", "num_void_cycles_detected", "std_cycle_metrics.num_void_cycles_detected"),
    ("avg_cycle_metrics.cycle_len_mean", "cycle_len_mean", "std_cycle_metrics.cycle_len_mean"),
    ("avg_cycle_metrics.cycle_len_cv", "cycle_len_cv", "std_cycle_metrics.cycle_len_cv"),
    ("avg_cycle_metrics.stability_score", "stability_score", "std_cycle_metrics.stability_score"),
    ("avg_cycle_metrics.percent_time_in_void", "percent_time_in_void", "std_cycle_metrics.percent_time_in_void"),
    ("avg_cycle_metrics.depth_mean", "depth_mean", "std_cycle_metrics.depth_mean"),
    ("avg_cycle_metrics.depth_min", "depth_min", "std_cycle_metrics.depth_min"),
    ("avg_final_meta_edge_score", "avg_final_meta_edge_score", "std_final_meta_edge_score"),
]

def get(js, dotted, default=None):
    cur = js
    for k in dotted.split("."):
        if isinstance(cur, dict) and k in cur:
            cur = cur[k]
        else:
            return default
    return cur

def build_tolerance(mult=2.0, rtol=0.2, min_atol=0.0):
    if not os.path.exists(SUMMARY):
        return None
    js = json.load(open(SUMMARY, "r", encoding="utf-8"))
    n = int(js.get("num_runs") or 1)
    sr = max(1, n)
    metrics = {}
    for avg_key, name, std_key in METRIC_MAP:
        avg = get(js, avg_key, None)
        if avg is None:
            continue
        std = get(js, std_key, None)
        if std is None:
            atol = max(min_atol, rtol * abs(float(avg)))
        else:
            se = float(std) / math.sqrt(sr)
            atol = max(min_atol, mult * se)
        metrics[name] = {"mode": "tolerance", "target": float(avg), "atol": float(atol), "rtol": float(rtol)}
    cfg = {"env": {"python": "3.10", "deps": []}, "data": [], "outputs": [{"path": SUMMARY, "metrics": metrics}]}
    write_json(TOL_OUT, cfg)
    return {"written": TOL_OUT, "metrics": len(metrics)}

status = {}
if os.path.exists(SUMMARY):
    strict_info = build_strict()
    tol_info = build_tolerance()
    status["state"] = "ready"
    status["strict"] = strict_info
    status["tolerance"] = tol_info
else:
    # Report any available v4.6 files
    files = sorted([p for p in glob.glob(os.path.join(BASE, "power_law_sim_*v4.6*")) if os.path.isfile(p)])
    status["state"] = "waiting_for_summary"
    status["found"] = files[:50]

print(json.dumps(status, indent=2, ensure_ascii=False))
